$r=$record;$a=$r['album'];$ed=$r['edition'];$private=!empty($a['draft_owner_id'])&&(int)$a['draft_owner_id']===\App\Core\Auth::id();
$options=static fn(array $rows,string $field='title'):array=>array_column($rows,$field,'id');
$artistOptions=$options($artists,'name');$labelOptions=$options($labels,'name');$mediaOptions=[];foreach($r['media'] as $m)$mediaOptions[$m['id']]='Soporte '.$m['position'].' · '.($m['format']??'Desconocido');
$trackOptions=$options($r['tracks']);$recordingOptions=$options($r['recordings']??[]);
$targets=['album:'.$a['id']=>'Álbum','edition:'.($ed['id']??0)=>'Edición'];foreach(['track'=>$r['tracks'],'recording'=>$r['recordings']??[],'work'=>$r['works']??[]] as $kind=>$rows)foreach($rows as $row)$targets[$kind.':'.$row['id']]=ucfirst($kind).' · '.$row['title'];
$form=function(string $op,string $heading,array $fields,array $values=[]) use ($r,$revision,$private,$old,$targets):void {
    $scope=in_array($op,['artist_identity','label_identity'],true)?'shared':($private?'private':'shared');
    if(in_array($op,['artist_identity','label_identity'],true))$values['identity_before_hash']=\App\Services\EncyclopediaManual::identityFingerprint($values);
    $entity=$values['id']??0;
    if(($old['operation']??'')===$op && (int)($old['entity_id']??0)===(int)$entity)$values=array_merge($values,$old);
    $key=($old['operation']??'')===$op && (int)($old['entity_id']??0)===(int)$entity?($old['key']??bin2hex(random_bytes(32))):bin2hex(random_bytes(32));
    ?><details class="card manual-section"><summary><?= e($heading) ?></summary><form method="post" action="<?= e(base_url('encyclopedia/manual/save')) ?>" data-operation="<?= e($op) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['vinyl']['Id'] ?>"><input type="hidden" name="operation" value="<?= e($op) ?>"><input type="hidden" name="entity_id" value="<?= (int)$entity ?>"><input type="hidden" name="revision" value="<?= (int)$revision ?>"><input type="hidden" name="key" value="<?= e($key) ?>"><input type="hidden" name="scope" value="<?= e($scope) ?>">
    <?php if(isset($values['identity_before_hash'])): ?><input type="hidden" name="identity_before_hash" value="<?= e($values['identity_before_hash']) ?>"><?php endif; ?>
    <div class="grid"><?php foreach($fields as $name=>$definition):[$label,$type,$extra]=$definition+[2=>null];$value=(string)($values[$name]??''); ?>
    <label><?= e($label) ?><?php if($type==='select'): ?><select name="<?= e($name) ?>"><option value="">Selecciona o deja desconocido</option><?php foreach($extra as $id=>$title): ?><option value="<?= e((string)$id) ?>" <?= $value===(string)$id?'selected':'' ?>><?= e((string)$title) ?> · #<?= e((string)$id) ?></option><?php endforeach; ?></select><?php elseif($type==='textarea'): ?><textarea name="<?= e($name) ?>" rows="3" maxlength="<?= (int)$extra ?>"><?= e($value) ?></textarea><?php else: ?><input name="<?= e($name) ?>" value="<?= e($value) ?>" maxlength="<?= (int)$extra ?>"><?php endif; ?></label>
    <?php endforeach; ?></div><label><input type="checkbox" name="confirm" required> <?= $scope==='private'?'Confirmo guardar en mi borrador musical privado':'Confirmo modificar estos metadatos compartidos; el cambio será visible para otros ejemplares relacionados' ?></label><button>Guardar información musical</button></form></details><?php
};
