<?php
$form('album','Álbum: título, clasificación y fecha',['title'=>['Título musical','text',255],'original_date'=>['Fecha original (AAAA, AAAA-MM o AAAA-MM-DD)','text',10],'release_type'=>['Tipo de publicación','text',80],'language'=>['Idioma','text',32],'description'=>['Descripción musical','textarea',10000]],$a);
$form('edition','Edición: países, fechas y características',['country'=>['País','text',80],'manufacture_country'=>['País de fabricación','text',80],'release_date'=>['Fecha de edición','text',10],'barcode'=>['Código de barras','text',64],'packaging'=>['Presentación','text',255],'edition_type'=>['Tipo de edición','text',120],'pressing_plant'=>['Planta de prensado','text',255],'remastered'=>['Remasterizada','select',['0'=>'No','1'=>'Sí']]],$ed);
foreach([...$r['media'],[]] as $m)$form('medium',empty($m)?'Añadir soporte':'Editar soporte '.$m['position'],['position'=>['Orden del soporte','text',5],'format'=>['Formato confirmado','text',80],'rpm'=>['Revoluciones por minuto','text',16],'diameter_inches'=>['Diámetro (pulgadas)','text',16],'color'=>['Color','text',120],'weight_grams'=>['Peso (gramos)','text',5]],$m);
$duration=static fn($t)=>$t['duration_ms']===null?'':sprintf('%d:%02d',intdiv((int)$t['duration_ms'],60000),intdiv((int)$t['duration_ms'],1000)%60);
foreach([...$r['tracks'],[]] as $t){if($t)$t['duration']=$duration($t);$form('track',empty($t)?'Añadir canción':'Editar canción '.$t['title'],['medium_id'=>['Soporte','select',$mediaOptions],'position'=>['Orden','text',5],'printed_number'=>['Número impreso','text',32],'side'=>['Cara del vinilo','text',16],'title'=>['Título','text',255],'duration'=>['Duración (m:ss)','text',16],'recording_id'=>['Grabación de esta edición','select',$recordingOptions]],$t);}
foreach([...($r['recordings']??[]),[]] as $rec){if($rec){$rec['duration']=$duration($rec);foreach($r['tracks'] as $t)if($t['recording_id']===$rec['id']){$rec['track_id']=$t['id'];break;}}$form('recording',empty($rec)?'Añadir grabación a una canción':'Editar grabación '.$rec['title'],['track_id'=>['Canción asociada','select',$trackOptions],'title'=>['Título de grabación','text',255],'duration'=>['Duración (m:ss)','text',16]],$rec);}
foreach([...($r['works']??[]),[]] as $w)$form('work',empty($w)?'Añadir composición':'Editar composición '.$w['title'],['recording_id'=>['Grabación asociada','select',$recordingOptions],'title'=>['Título de composición','text',255]],$w);
foreach([...$r['credits'],[]] as $c){foreach(['album','edition','track','recording','work'] as $kind)if(!empty($c[$kind.'_id']))$c['target_key']=$kind.':'.$c[$kind.'_id'];$form('credit',empty($c)?'Añadir crédito':'Editar crédito '.($c['name']??$c['organisation']).' · '.$c['role'],['target_key'=>['Entidad a la que corresponde','select',$targets],'artist_id'=>['Identidad existente verificada','select',$artistOptions],'artist_kind'=>['Tipo para identidad nueva','select',['unknown'=>'Desconocido','person'=>'Persona','group'=>'Grupo']],'artist_name'=>['Nombre nuevo (solo si no hay identidad coincidente)','text',255],'role'=>['Función (producer, engineer, composer, lyricist, performer, mix…)','text',120],'instrument'=>['Instrumento confirmado','text',120],'credited_as'=>['Nombre acreditado','text',255]],$c);}
if($sharedEditor){
    ?><p class="alert">Corrección editorial de identidades: cambiar el nombre o tipo afecta a todas sus apariciones, también en otros álbumes. No se fusionan personas o sellos automáticamente.</p><?php
    $participantIds=array_unique(array_filter(array_merge(array_column($r['artists'],'id'),array_column($r['credits'],'artist_id'))));
    foreach($artists as $actor)if(in_array($actor['id'],$participantIds))$form('artist_identity','Corrección editorial de identidad '.$actor['name'],['name'=>['Nombre canónico','text',255],'kind'=>['Tipo','select',['unknown'=>'Desconocido','person'=>'Persona','group'=>'Grupo']]],$actor);
    foreach($r['labels'] as $label)$form('label_identity','Corrección editorial del sello '.$label['name'],['name'=>['Nombre canónico','text',255]],$label);
}
$form('artist','Artista principal o grupo',['artist_id'=>['Identidad verificada','select',$artistOptions],'artist_kind'=>['Tipo para identidad nueva','select',['unknown'=>'Desconocido','person'=>'Persona','group'=>'Grupo']],'artist_name'=>['Nombre nuevo si no existe','text',255],'position'=>['Orden de artista','text',5],'credited_as'=>['Nombre acreditado','text',255]]);
foreach([...$r['labels'],[]] as $label){if($label){$label['label_id']=$label['id'];$label['old_label_id']=$label['id'];$label['old_catalogue_number']=$label['catalogue_number'];}
$form('label',empty($label)?'Añadir sello y catálogo':'Corregir sello y catálogo '.$label['name'],['label_id'=>['Sello existente verificado','select',$labelOptions],'label_name'=>['Nombre nuevo si no existe','text',255],'catalogue_number'=>['Número de catálogo','text',120],'old_label_id'=>['Identificador anterior (no alterar)','text',12],'old_catalogue_number'=>['Catálogo anterior (no alterar)','text',120]],$label);}
foreach([...$r['genres'],[]] as $genre){$genre['term_id']=$genre['id']??'';$form('genre',empty($genre['id'])?'Añadir clasificación musical':'Corregir clasificación '.$genre['name'],['kind'=>['Clase','select',['genre'=>'Género','style'=>'Estilo']],'name'=>['Nombre','text',120],'term_id'=>['Identificador anterior (no alterar)','text',12]],$genre);}
?>
